function(container, apiUrl, tables) {
  const notificationListEl = container.querySelector('#notification-list');
  const detailPanelEl = container.querySelector('#detail-panel');
  const noSelectionEl = container.querySelector('#no-selection');
  const statusFilterEl = container.querySelector('[data-testid="status-filter"]');
  const priorityFilterEl = container.querySelector('[data-testid="priority-filter"]');
  const dataTypeFilterEl = container.querySelector('[data-testid="data-type-filter"]');
  const dateFromEl = container.querySelector('[data-testid="date-from"]');
  const searchBtnEl = container.querySelector('[data-testid="search-button"]');

  let allNotifications = [];
  let selectedNotificationId = null;

  // 通知データの取得と初期化
  async function loadNotifications() {
    const logs = await window.aivicApi.list(2); // 営業データ異常検出ログ（tableIndex=2）
    const missingLogs = await window.aivicApi.list(10); // 不足データ通知ログ（tableIndex=10）

    allNotifications = [];

    // 異常検出ログを通知に変換
    if (logs && Array.isArray(logs)) {
      logs.forEach(log => {
        allNotifications.push({
          id: log.異常検出ログID || log.id,
          type: '異常値',
          title: `${log.異常フィールド名 || 'フィールド'} - ${log.異常タイプ || '異常'}`,
          status: log.対応状況 || '未対応',
          priority: log.重要度 || '中',
          detectedAt: log.検出日時 || new Date().toISOString(),
          salesDataId: log.営業データID,
          ruleId: log.検証ルールID,
          anomalyType: log.異常タイプ,
          field: log.異常フィールド名,
          detectedValue: log.検出値,
          expectedValue: log.期待値,
          affectsBilling: log.請求処理への影響 || false,
          responseComment: log.対応コメント || '',
          respondedAt: log.対応日時,
          respondedBy: log.対応者,
          source: 'anomaly'
        });
      });
    }

    // 不足データ通知ログを通知に変換
    if (missingLogs && Array.isArray(missingLogs)) {
      missingLogs.forEach(log => {
        allNotifications.push({
          id: log.不足データ通知ログID || log.id,
          type: '不足データ',
          title: `${log.不足項目名 || '項目'} - 不足`,
          status: log.通知ステータス || '未対応',
          priority: log.重要度レベル || '中',
          detectedAt: log.通知日時 || new Date().toISOString(),
          salesDataId: log.営業データID,
          ruleId: log.検証ルールID,
          missingField: log.不足項目名,
          affectsBilling: log.請求影響フラグ || false,
          responseComment: log.補正内容 || '',
          respondedAt: log.対応完了日時,
          respondedBy: log.通知対象者,
          source: 'missing'
        });
      });
    }

    // 日時でソート（新しい順）
    allNotifications.sort((a, b) => new Date(b.detectedAt) - new Date(a.detectedAt));

    renderNotificationList(allNotifications);
  }

  // フィルタリング
  function applyFilters() {
    const status = statusFilterEl.value;
    const priority = priorityFilterEl.value;
    const dataType = dataTypeFilterEl.value;
    const dateFrom = dateFromEl.value;

    let filtered = allNotifications;

    if (status) {
      filtered = filtered.filter(n => n.status === status);
    }
    if (priority) {
      filtered = filtered.filter(n => n.priority === priority);
    }
    if (dataType) {
      filtered = filtered.filter(n => n.type === dataType);
    }
    if (dateFrom) {
      const fromDate = new Date(dateFrom);
      filtered = filtered.filter(n => new Date(n.detectedAt) >= fromDate);
    }

    renderNotificationList(filtered);
  }

  // 通知一覧の描画
  function renderNotificationList(notifications) {
    notificationListEl.innerHTML = '';

    if (notifications.length === 0) {
      notificationListEl.innerHTML = '<div style="padding: 16px; color: var(--text-muted); font-size: 12px; text-align: center;">通知がありません</div>';
      return;
    }

    notifications.forEach(notification => {
      const item = document.createElement('div');
      item.className = 'notification-item';
      item.dataset.id = notification.id;
      item.style.cssText = `
        padding: 12px 12px;
        border-bottom: 1px solid rgba(255,255,255,0.08);
        cursor: pointer;
        transition: background 0.15s;
        background: ${selectedNotificationId === notification.id ? 'rgba(255,255,255,0.06)' : 'transparent'};
      `;

      const statusColor = {
        '未対応': '#ff6b6b',
        '対応中': '#ffa500',
        '解決': '#51cf66',
        '無視': '#868e96'
      }[notification.status] || '#868e96';

      const priorityColor = {
        '高': '#ff6b6b',
        '中': '#ffa500',
        '低': '#74c0fc'
      }[notification.priority] || '#868e96';

      item.innerHTML = `
        <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; margin-bottom: 6px;">
          <div style="flex: 1;">
            <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 2px;">${escapeHtml(notification.title)}</div>
            <div style="font-size: 11px; color: var(--text-muted);">${notification.type}</div>
          </div>
          <div style="display: flex; gap: 4px;">
            <span style="display: inline-block; padding: 2px 6px; font-size: 10px; background: ${statusColor}; color: #fff; border-radius: 3px; font-weight: 500;">${notification.status}</span>
            <span style="display: inline-block; padding: 2px 6px; font-size: 10px; background: ${priorityColor}; color: #fff; border-radius: 3px; font-weight: 500;">${notification.priority}</span>
          </div>
        </div>
        <div style="font-size: 10px; color: var(--text-muted);">${formatDate(notification.detectedAt)}</div>
        ${notification.affectsBilling ? '<div style="font-size: 10px; color: #ff6b6b; margin-top: 4px; font-weight: 500;">⚠ 請求に影響</div>' : ''}
      `;

      item.addEventListener('click', () => {
        selectedNotificationId = notification.id;
        renderNotificationList(allNotifications.filter(n => {
          const status = statusFilterEl.value;
          const priority = priorityFilterEl.value;
          const dataType = dataTypeFilterEl.value;
          const dateFrom = dateFromEl.value;
          let match = true;
          if (status) match = match && n.status === status;
          if (priority) match = match && n.priority === priority;
          if (dataType) match = match && n.type === dataType;
          if (dateFrom) match = match && new Date(n.detectedAt) >= new Date(dateFrom);
          return match;
        }));
        renderDetailPanel(notification);
      });

      notificationListEl.appendChild(item);
    });
  }

  // 詳細パネルの描画
  function renderDetailPanel(notification) {
    noSelectionEl.style.display = 'none';
    detailPanelEl.style.display = 'block';

    const statusOptions = ['未対応', '対応中', '解決', '無視'];
    const priorityOptions = ['高', '中', '低'];

    let detailHTML = `
      <div style="margin-bottom: 20px;">
        <h2 style="margin: 0 0 12px 0; font-size: 14px; font-weight: 600; color: var(--text);">${escapeHtml(notification.title)}</h2>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: 12px; margin-bottom: 16px;">
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">通知種別</div>
            <div style="color: var(--text); font-weight: 500;">${notification.type}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">検出日時</div>
            <div style="color: var(--text); font-weight: 500;">${formatDate(notification.detectedAt)}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">営業データID</div>
            <div style="color: var(--text); font-weight: 500; font-family: monospace; font-size: 11px;">${notification.salesDataId ? notification.salesDataId.substring(0, 12) + '...' : '-'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">請求への影響</div>
            <div style="color: ${notification.affectsBilling ? '#ff6b6b' : '#51cf66'}; font-weight: 500;">${notification.affectsBilling ? '⚠ あり' : 'なし'}</div>
          </div>
        </div>
      </div>

      <div style="border-top: 1px solid rgba(255,255,255,0.08); padding-top: 16px; margin-bottom: 20px;">
        <h3 style="margin: 0 0 12px 0; font-size: 12px; font-weight: 600; color: var(--text); text-transform: uppercase; letter-spacing: 0.5px;">異常内容</h3>
    `;

    if (notification.source === 'anomaly') {
      detailHTML += `
        <div style="background: rgba(255,255,255,0.04); padding: 12px; border-radius: 4px; font-size: 12px; margin-bottom: 12px;">
          <div style="margin-bottom: 8px;">
            <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">異常タイプ</div>
            <div style="color: var(--text);">${notification.anomalyType || '-'}</div>
          </div>
          <div style="margin-bottom: 8px;">
            <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">フィールド</div>
            <div style="color: var(--text);">${notification.field || '-'}</div>
          </div>
          <div style="margin-bottom: 8px;">
            <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">検出値</div>
            <div style="color: var(--text); font-family: monospace; font-size: 11px; word-break: break-all;">${notification.detectedValue || '-'}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">期待値</div>
            <div style="color: var(--text); font-family: monospace; font-size: 11px; word-break: break-all;">${notification.expectedValue || '-'}</div>
          </div>
        </div>
      `;
    } else if (notification.source === 'missing') {
      detailHTML += `
        <div style="background: rgba(255,255,255,0.04); padding: 12px; border-radius: 4px; font-size: 12px; margin-bottom: 12px;">
          <div>
            <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">不足項目</div>
            <div style="color: var(--text);">${notification.missingField || '-'}</div>
          </div>
        </div>
      `;
    }

    detailHTML += `
      </div>

      <div style="border-top: 1px solid rgba(255,255,255,0.08); padding-top: 16px; margin-bottom: 20px;">
        <h3 style="margin: 0 0 12px 0; font-size: 12px; font-weight: 600; color: var(--text); text-transform: uppercase; letter-spacing: 0.5px;">対応状況</h3>
        <div style="margin-bottom: 12px;">
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px; font-weight: 500;">ステータス</label>
          <select id="response-status" style="width: 100%; padding: 6px 8px; font-size: 12px; border: 1px solid rgba(255,255,255,0.18); background: rgba(0,0,0,0.25); color: var(--text); border-radius: 4px;">
            ${statusOptions.map(s => `<option value="${s}" ${s === notification.status ? 'selected' : ''}>${s}</option>`).join('')}
          </select>
        </div>
        <div style="margin-bottom: 12px;">
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px; font-weight: 500;">対応コメント</label>
          <textarea id="response-comment" data-testid="response-comment" style="width: 100%; padding: 8px; font-size: 12px; border: 1px solid rgba(255,255,255,0.18); background: rgba(0,0,0,0.25); color: var(--text); border-radius: 4px; font-family: inherit; resize: vertical; min-height: 80px;">${notification.responseComment || ''}</textarea>
        </div>
        ${notification.respondedAt ? `
          <div style="font-size: 11px; color: var(--text-muted); padding: 8px; background: rgba(255,255,255,0.04); border-radius: 4px;">
            対応者: ${notification.respondedBy || '-'} | 対応日時: ${formatDate(notification.respondedAt)}
          </div>
        ` : ''}
      </div>

      <div style="display: flex; gap: 8px;">
        <button id="save-response-btn" data-testid="save-response-button" style="flex: 1; padding: 8px 12px; font-size: 12px; background: var(--primary); color: #fff; border: none; border-radius: 4px; cursor: pointer; font-weight: 500;">対応を保存</button>
        <button id="close-detail-btn" style="flex: 0 0 auto; padding: 8px 12px; font-size: 12px; background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; cursor: pointer;">閉じる</button>
      </div>
    `;

    detailPanelEl.innerHTML = detailHTML;

    // イベントリスナー
    const saveBtn = detailPanelEl.querySelector('#save-response-btn');
    const closeBtn = detailPanelEl.querySelector('#close-detail-btn');
    const statusSelect = detailPanelEl.querySelector('#response-status');
    const commentTextarea = detailPanelEl.querySelector('#response-comment');

    saveBtn.addEventListener('click', async () => {
      const newStatus = statusSelect.value;
      const newComment = commentTextarea.value;

      // 対応状況を更新
      if (notification.source === 'anomaly') {
        await window.aivicApi.update(2, notification.id, {
          対応状況: newStatus,
          対応コメント: newComment,
          対応日時: new Date().toISOString(),
          対応者: 'current-user' // 実際にはセッションから取得
        });
      } else if (notification.source === 'missing') {
        await window.aivicApi.update(10, notification.id, {
          通知ステータス: newStatus,
          補正内容: newComment,
          対応完了日時: newStatus === '解決' ? new Date().toISOString() : null
        });
      }

      // UI更新
      notification.status = newStatus;
      notification.responseComment = newComment;
      notification.respondedAt = new Date().toISOString();

      // 一覧を再描画
      applyFilters();
      renderDetailPanel(notification);
    });

    closeBtn.addEventListener('click', () => {
      selectedNotificationId = null;
      noSelectionEl.style.display = 'flex';
      detailPanelEl.style.display = 'none';
    });
  }

  // ユーティリティ関数
  function formatDate(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  }

  function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // イベントリスナー
  searchBtnEl.addEventListener('click', applyFilters);
  statusFilterEl.addEventListener('change', applyFilters);
  priorityFilterEl.addEventListener('change', applyFilters);
  dataTypeFilterEl.addEventListener('change', applyFilters);
  dateFromEl.addEventListener('change', applyFilters);

  // 初期化
  loadNotifications();
}

function(container, apiUrl, tables) {
  const logicTbody = container.querySelector('#logic-tbody');
  const logicNameInput = container.querySelector('[data-testid="logic-name"]');
  const billingItemSelect = container.querySelector('[data-testid="billing-item-select"]');
  const aggregationRuleSelect = container.querySelector('[data-testid="aggregation-rule-select"]');
  const conditionEditor = container.querySelector('[data-testid="condition-editor"]');
  const applyValidationCheckbox = container.querySelector('[data-testid="apply-validation-rules"]');
  const logicEnabledCheckbox = container.querySelector('[data-testid="logic-enabled"]');
  const testDataSelect = container.querySelector('[data-testid="test-data-select"]');
  const runValidationBtn = container.querySelector('[data-testid="run-validation-btn"]');
  const validationResult = container.querySelector('#validation-result');
  const anomalyLog = container.querySelector('#anomaly-log');
  const newLogicBtn = container.querySelector('[data-testid="new-logic-btn"]');
  const saveLogicBtn = container.querySelector('[data-testid="save-logic-btn"]');
  const cancelLogicBtn = container.querySelector('[data-testid="cancel-logic-btn"]');
  const logicCountSpan = container.querySelector('[data-testid="logic-count"]');

  let currentLogicId = null;
  let logicList = [];

  // ロジック一覧を取得して表示
  async function loadLogicList() {
    try {
      const logics = await window.aivicApi.list(0); // テーブルインデックス 0: 請求ロジック定義
      if (!logics) return;

      logicList = logics;
      logicCountSpan.textContent = logics.length;

      logicTbody.innerHTML = '';
      logics.forEach(logic => {
        const row = document.createElement('tr');
        row.className = 'logic-row';
        row.dataset.id = logic.id;
        row.style.cssText = 'background: var(--bg-main); cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.04);';

        const statusBadge = logic.enabled 
          ? '<span style="display: inline-block; padding: 2px 6px; background: rgba(76, 175, 80, 0.2); color: #4caf50; border-radius: 3px; font-size: 10px;">有効</span>'
          : '<span style="display: inline-block; padding: 2px 6px; background: rgba(158, 158, 158, 0.2); color: #9e9e9e; border-radius: 3px; font-size: 10px;">無効</span>';

        row.innerHTML = `
          <td style="padding: 8px 12px; color: var(--text);">${logic.name || '（未名称）'}</td>
          <td style="padding: 8px 12px; text-align: center;">${statusBadge}</td>
        `;

        row.addEventListener('click', () => selectLogic(logic));
        logicTbody.appendChild(row);
      });
    } catch (err) {
      console.error('ロジック一覧の取得に失敗:', err);
    }
  }

  // ロジックを選択
  function selectLogic(logic) {
    currentLogicId = logic.id;
    logicNameInput.value = logic.name || '';
    billingItemSelect.value = logic.billingItem || '';
    aggregationRuleSelect.value = logic.aggregationRule || '';
    conditionEditor.value = logic.condition || '';
    applyValidationCheckbox.checked = logic.applyValidation || false;
    logicEnabledCheckbox.checked = logic.enabled !== false;

    // 行をハイライト
    container.querySelectorAll('.logic-row').forEach(r => r.style.opacity = '0.6');
    container.querySelector(`[data-id="${logic.id}"]`).style.opacity = '1';
  }

  // 新規ロジック作成
  newLogicBtn.addEventListener('click', () => {
    currentLogicId = null;
    logicNameInput.value = '';
    billingItemSelect.value = '';
    aggregationRuleSelect.value = '';
    conditionEditor.value = '';
    applyValidationCheckbox.checked = false;
    logicEnabledCheckbox.checked = true;
    validationResult.style.display = 'none';

    container.querySelectorAll('.logic-row').forEach(r => r.style.opacity = '0.6');
  });

  // ロジック保存
  saveLogicBtn.addEventListener('click', async () => {
    const logicData = {
      name: logicNameInput.value.trim(),
      billingItem: billingItemSelect.value,
      aggregationRule: aggregationRuleSelect.value,
      condition: conditionEditor.value.trim(),
      applyValidation: applyValidationCheckbox.checked,
      enabled: logicEnabledCheckbox.checked,
    };

    if (!logicData.name) {
      alert('ロジック名を入力してください');
      return;
    }

    try {
      if (currentLogicId) {
        await window.aivicApi.update(0, currentLogicId, logicData);
      } else {
        await window.aivicApi.save(0, logicData);
      }
      loadLogicList();
      validationResult.style.display = 'none';
    } catch (err) {
      console.error('ロジック保存に失敗:', err);
    }
  });

  // キャンセル
  cancelLogicBtn.addEventListener('click', () => {
    logicNameInput.value = '';
    billingItemSelect.value = '';
    aggregationRuleSelect.value = '';
    conditionEditor.value = '';
    currentLogicId = null;
    validationResult.style.display = 'none';
    container.querySelectorAll('.logic-row').forEach(r => r.style.opacity = '0.6');
  });

  // 検証実行
  runValidationBtn.addEventListener('click', async () => {
    if (!currentLogicId && !logicNameInput.value) {
      alert('ロジックを選択または作成してください');
      return;
    }

    if (!testDataSelect.value) {
      alert('テストデータセットを選択してください');
      return;
    }

    try {
      // テスト実行（シミュレーション）
      const testCount = Math.floor(Math.random() * 100) + 50;
      const successCount = Math.floor(testCount * 0.92);
      const failedCount = Math.floor(testCount * 0.05);
      const warningCount = testCount - successCount - failedCount;

      container.querySelector('[data-testid="validation-count"]').textContent = testCount;
      container.querySelector('[data-testid="validation-success"]').textContent = successCount;
      container.querySelector('[data-testid="validation-failed"]').textContent = failedCount;
      container.querySelector('[data-testid="validation-warning"]').textContent = warningCount;

      validationResult.style.display = 'block';

      // 品質スコア計算
      const qualityScore = Math.round((successCount / testCount) * 100);
      container.querySelector('[data-testid="quality-score"]').textContent = qualityScore;

      // 異常ログ更新（シミュレーション）
      const anomalies = [
        { type: '警告', message: '返品額が負数', dataId: 'data-20240115-001', time: '2024-01-15 14:32:15', color: '#ff9800' },
        { type: 'エラー', message: '必須項目欠落', dataId: 'data-20240115-002', time: '2024-01-15 14:31:42', color: '#f44336' },
        { type: '警告', message: '単価が0円', dataId: 'data-20240115-003', time: '2024-01-15 14:30:18', color: '#ff9800' },
      ];

      anomalyLog.innerHTML = anomalies.map(a => `
        <div style="padding: 8px; background: rgba(0,0,0,0.2); border-radius: 3px; border-left: 3px solid ${a.color}; margin-bottom: 8px;">
          <div style="color: var(--text); font-weight: 500;">${a.type === '警告' ? '⚠' : '✗'} ${a.type}: ${a.message}</div>
          <div style="font-size: 10px; margin-top: 4px;">営業データID: ${a.dataId} | 検出日時: ${a.time}</div>
        </div>
      `).join('');

    } catch (err) {
      console.error('検証実行に失敗:', err);
    }
  });

  // 初期化
  loadLogicList();
}

function(container, apiUrl, tables) {
  const tableIndex = 0; // 営業データテーブル
  let allRecords = [];
  let selectedRecordId = null;

  // DOM要素の取得
  const customerIdInput = container.querySelector('[data-testid="customer-id-input"]');
  const serviceTypeSelect = container.querySelector('[data-testid="service-type-select"]');
  const startDateInput = container.querySelector('[data-testid="start-date-input"]');
  const endDateInput = container.querySelector('[data-testid="end-date-input"]');
  const qualityStatusSelect = container.querySelector('[data-testid="quality-status-select"]');
  const billingFlagSelect = container.querySelector('[data-testid="billing-flag-select"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const resetBtn = container.querySelector('[data-testid="reset-button"]');
  const exportBtn = container.querySelector('[data-testid="export-csv-button"]');
  const recordTbody = container.querySelector('#record-tbody');
  const resultCount = container.querySelector('[data-testid="result-count"]');
  const detailPanel = container.querySelector('#detail-panel');
  const detailContent = container.querySelector('#detail-content');
  const closeDetailBtn = container.querySelector('#close-detail-btn');
  const viewValidationBtn = container.querySelector('#view-validation-btn');
  const viewAnomalyBtn = container.querySelector('#view-anomaly-btn');

  // 初期データ取得
  async function loadData() {
    const records = await window.aivicApi.list(tableIndex);
    if (records) {
      allRecords = records;
      renderTable(allRecords);
    }
  }

  // テーブル描画
  function renderTable(records) {
    recordTbody.innerHTML = '';
    records.forEach(record => {
      const row = document.createElement('tr');
      row.dataset.id = record.id || record['営業データID'];
      row.style.cssText = 'border-bottom: 1px solid rgba(255,255,255,0.06); cursor: pointer; transition: background 0.15s;';
      row.onmouseover = () => row.style.background = 'rgba(255,255,255,0.04)';
      row.onmouseout = () => row.style.background = 'transparent';
      row.onclick = () => showDetail(record);

      const qualityBadge = getQualityBadge(record['データ品質ステータス'] || 'normal');
      const billingFlag = record['請求対象フラグ'] ? '○' : '×';
      const billedFlag = record['請求済みフラグ'] ? '○' : '×';

      row.innerHTML = `
        <td style="padding: 8px 12px; color: var(--text);">${(record['営業データID'] || '').substring(0, 12)}</td>
        <td style="padding: 8px 12px; color: var(--text);">${record['顧客ID'] || '-'}</td>
        <td style="padding: 8px 12px; color: var(--text);">${record['顧客名'] || '-'}</td>
        <td style="padding: 8px 12px; color: var(--text);">${record['サービス名'] || '-'}</td>
        <td style="padding: 8px 12px; color: var(--text); text-align: right;">${(record['取引金額'] || 0).toLocaleString()}円</td>
        <td style="padding: 8px 12px; text-align: center;">${qualityBadge}</td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text);">${billingFlag}</td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text);">${billedFlag}</td>
      `;
      recordTbody.appendChild(row);
    });

    resultCount.textContent = `検索結果: ${records.length}件`;
  }

  // 品質ステータスバッジ
  function getQualityBadge(status) {
    const statusMap = {
      'normal': { label: '正常', color: '#4ade80' },
      'warning': { label: '警告', color: '#facc15' },
      'error': { label: 'エラー', color: '#ef4444' }
    };
    const info = statusMap[status] || statusMap['normal'];
    return `<span style="display: inline-block; padding: 2px 8px; background: ${info.color}20; color: ${info.color}; border-radius: 3px; font-size: 11px; font-weight: 500;">${info.label}</span>`;
  }

  // 詳細パネル表示
  function showDetail(record) {
    selectedRecordId = record.id || record['営業データID'];
    detailPanel.style.display = 'flex';

    const html = `
      <div style="display: grid; gap: 12px;">
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">営業データID</div>
          <div style="font-weight: 500; color: var(--text);">${record['営業データID'] || '-'}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">顧客ID / 顧客名</div>
          <div style="font-weight: 500; color: var(--text);">${record['顧客ID'] || '-'} / ${record['顧客名'] || '-'}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">取引日</div>
          <div style="font-weight: 500; color: var(--text);">${record['取引日'] ? new Date(record['取引日']).toLocaleDateString('ja-JP') : '-'}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">取引金額</div>
          <div style="font-weight: 500; color: var(--text);">${(record['取引金額'] || 0).toLocaleString()}円</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">取引種別</div>
          <div style="font-weight: 500; color: var(--text);">${record['取引種別'] || '-'}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">商品ID / 数量 / 単価</div>
          <div style="font-weight: 500; color: var(--text);">${record['商品ID'] || '-'} / ${record['数量'] || 0}個 / ${(record['単価'] || 0).toLocaleString()}円</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">データ品質ステータス</div>
          <div>${getQualityBadge(record['データ品質ステータス'] || 'normal')}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">請求対象 / 請求済み</div>
          <div style="font-weight: 500; color: var(--text);">${record['請求対象フラグ'] ? '対象' : '対象外'} / ${record['請求済みフラグ'] ? '済み' : '未処理'}</div>
        </div>
        ${record['品質エラー内容'] ? `
          <div style="padding: 8px; background: rgba(239,68,68,0.1); border-left: 3px solid #ef4444; border-radius: 3px;">
            <div style="font-size: 11px; color: #ef4444; font-weight: 500; margin-bottom: 2px;">エラー内容</div>
            <div style="font-size: 11px; color: var(--text);">${record['品質エラー内容']}</div>
          </div>
        ` : ''}
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">摘要</div>
          <div style="font-size: 12px; color: var(--text); line-height: 1.4;">${record['摘要'] || '-'}</div>
        </div>
      </div>
    `;
    detailContent.innerHTML = html;
  }

  // 検索フィルタ適用
  function applyFilters() {
    const customerId = customerIdInput.value.trim();
    const serviceType = serviceTypeSelect.value;
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const qualityStatus = qualityStatusSelect.value;
    const billingFlag = billingFlagSelect.value;

    const filtered = allRecords.filter(record => {
      if (customerId && !record['顧客ID']?.includes(customerId)) return false;
      if (serviceType && record['サービス名'] !== serviceType) return false;
      if (startDate && new Date(record['取引日']) < new Date(startDate)) return false;
      if (endDate && new Date(record['取引日']) > new Date(endDate)) return false;
      if (qualityStatus && record['データ品質ステータス'] !== qualityStatus) return false;
      if (billingFlag !== '' && String(record['請求対象フラグ']) !== billingFlag) return false;
      return true;
    });

    renderTable(filtered);
  }

  // リセット
  function resetFilters() {
    customerIdInput.value = '';
    serviceTypeSelect.value = '';
    startDateInput.value = '';
    endDateInput.value = '';
    qualityStatusSelect.value = '';
    billingFlagSelect.value = '';
    renderTable(allRecords);
  }

  // CSVエクスポート
  function exportCSV() {
    if (allRecords.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['営業データID', '顧客ID', '顧客名', 'サービス名', '取引日', '取引金額', '取引種別', '商品ID', '数量', '単価', 'データ品質ステータス', '請求対象フラグ', '請求済みフラグ', '摘要'];
    const rows = allRecords.map(record =>
      headers.map(h => {
        const val = record[h];
        if (val === null || val === undefined) return '';
        if (typeof val === 'string' && (val.includes(',') || val.includes('"') || val.includes('\n'))) {
          return `"${val.replace(/"/g, '""')}"`;
        }
        return val;
      }).join(',')
    );

    const csv = '\uFEFF' + headers.join(',') + '\n' + rows.join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `営業データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー
  searchBtn.addEventListener('click', applyFilters);
  resetBtn.addEventListener('click', resetFilters);
  exportBtn.addEventListener('click', exportCSV);
  closeDetailBtn.addEventListener('click', () => {
    detailPanel.style.display = 'none';
    selectedRecordId = null;
  });

  viewValidationBtn.addEventListener('click', () => {
    if (selectedRecordId) {
      window.showScreen('scr-1782111099986'); // データ品質検証結果確認
    }
  });

  viewAnomalyBtn.addEventListener('click', () => {
    if (selectedRecordId) {
      window.showScreen('scr-1782111120079'); // 不足データ・異常通知確認
    }
  });

  // 初期ロード
  loadData();
}
